-- Phase 5c-2b: the sect tuning group gained `skills` (the skills the sect teaches for cống hiến). A row an Admin has edited is NOT dropped: the key is written into it with its default
-- when it lacks it, so the edits stay and the row stays valid. (Nothing else changes: the skill rows are made when a member buys one.)
UPDATE game_tuning SET value = json_set(value, '$.skills', json('[{"skill":"tm_ho_than","cost":150,"minLevel":1,"minRank":0},{"skill":"tm_hoi_xuan","cost":200,"minLevel":1,"minRank":0},{"skill":"tm_tran_phap","cost":500,"minLevel":2,"minRank":0},{"skill":"tm_chien_y","cost":1200,"minLevel":3,"minRank":0},{"skill":"tm_kiem_tran","cost":3000,"minLevel":4,"minRank":0},{"skill":"tm_tam_phap","cost":8000,"minLevel":5,"minRank":0}]')) WHERE name = 'sect' AND json_extract(value, '$.skills') IS NULL;
